/* /works/split — the instrument. Generated by tools/port-tools.py; edit the
   artifact and re-run rather than editing here.
   ⛔ NOT INLINE, and not a preference: tools/audit.py balances every page
   as markup, and a script carrying '<div…>' strings is unparseable to it. */

(function(){
  var $=function(i){return document.getElementById(i);};
  var M=function(c){ return '$'+(c/100).toFixed(2); };
  // ⭐ A YEAR OF TRADE IS NOT AN ORDER. M() is built for one order — cents matter on
  //   $74.29 and read as noise on $24000.00, which is how the monthly figures came
  //   out once they were computed from a month of food rather than a count of orders.
  //   Whole dollars, grouped, for anything at that scale.
  var MB=function(c){ return '$'+Math.round(c/100).toLocaleString('en-US'); };

  // ◆ Published 2026 rates, for comparison only.
  var RIVALS=[
    ['DoorDash Basic',0.15],
    ['Uber Eats Lite',0.20],
    ['DoorDash Plus',0.25],
    ['Uber Eats Premium',0.30],
    ['Grubhub + delivery',0.30]
  ];


  // One payment, divided once. Band heights are proportional to money, so the
  // picture is the arithmetic rather than an illustration of it.
  // ⛔ THE SANKEY IS GONE, AND IT WAS THE THIRD TELLING. It drew what the two lists
  //   below it already state precisely — left side "the customer pays", right side "and
  //   it is owed to" — plus a legend restating both as percentages. Three
  //   representations of one decomposition, of which it was the least exact, the hardest
  //   to trace, and the only one BROKEN: "Service charge" sat at x=-13, clipped off the
  //   left edge of its own viewBox on the live page.
  //   ⭐ The customer bars below do the visual job now, comparatively, which the sankey
  //   never did (Jacob, 2026-09-13: "is all this necessary?").

  // ⭐ The two division ratios live here rather than on inputs, because the
  // control is a bar the reader divides, not two sliders whose bases are a
  // screenful apart. The bar is drawn from the MONEY
  // of it. Courier is paid from the service charge; Local Host and the Ward divide
  // what the courier leaves PLUS the commission — so the two ratios have
  // different bases, and only the bar makes that legible.
  // ⛔ THE LOCAL HOST IS NOT PAID BY THE ORDER, so the order does not draw them a
  //   slice. They are salaried by their own neighbourhood out of what the Ward
  //   collects there, annually, plus a courtesy that comes to pennies on one order —
  //   so a per-order slice implied a payment that does not happen. It was also the
  //   term that DRIFTED: this page said "40% of the rest" for a day after The Ask
  //   stopped paying the host that way. The claim it carried survives as a line on
  //   the Ward's own slice.
  //   ⭐ And removing it cost nothing: the host slice is carved AFTER the business
  //   and the courier are paid, so it never moved the number this page exists for.
  var COUR=0.75;
  var CAP=0.15;   // NYC · SF · Denver · Seattle · DC
  // ◆ Published consumer-side fees on the major platforms, 2026.
  var INCUMBENT_SERVICE=0.15, INCUMBENT_DELIVERY=299;
  // ○ THE ONE FIGURE ON THIS PAGE NOBODY PUBLISHES — a restaurant raising its menu
  //   prices to survive a 30% commission. It was a DIAL, which invited the reader to
  //   tune the number that decides the customer comparison, and that is the opposite
  //   of how every other incumbent figure here is handled: sourced, fixed, stated.
  //   Widely documented, so it stays; a slider, so it went (Jacob, 2026-09-13, third
  //   time of asking: "these controls don't do anything useful").

  // ◆ The Ask's food-per-restaurant-per-month, in cents. Shared, and checked.
  var MONTHLY=800000;
  var PROC={r:290,f:30};
  // ⭐ A payments institution that owns the rails is its own acquirer, so the
  // processing line stops being a cost paid out and becomes a rate paid to
  // itself — an on-us transaction internalises interchange as well as the
  // markup. ⛔ THIS FIGURE IS A SCENARIO, NOT A PUBLISHED RATE. Adyen and the
  // others describe volume pricing as custom; nobody publishes a number here,
  // and the page must not imply one was quoted.
  // ⛔ Two honest destinations for the difference, and the page makes you pick:
  // charge the customer less, or charge the same and keep it — NAMED as the
  // Ward's, never left sitting in a line labelled "processing".
  var INHOUSE={r:25,f:10};
  var owner='indep';
  // ⭐ THE MARKUP IS A PICTURE, NOT A SENTENCE. Two bars to ONE scale: the food block
  //   on the incumbent's bar is visibly bigger because the menu is marked up, and the
  //   bar is longer because the customer pays more. Nothing to read — the difference
  //   is the shape (Jacob, 2026-09-13: "split out the whole customer bar the way we
  //   did with what cary collects").
  // ⭐ ONE TOTAL, DIVIDED TWICE, AT TRUE SCALE. "What the customer pays" and "What
  //   Cary collects" were two decompositions of overlapping money in two columns —
  //   and Cary's pot turned out to be exactly the non-business part of the second
  //   division ($32.18 + $20.47 + $0.74 = $53.39 on a $195 order). So they combine:
  //   the same bar length, split once by WHAT YOU ARE CHARGED and once by WHO
  //   RECEIVES IT, with the restaurant included, which is the whole transaction.
  //   ⛔ IT COSTS THE ZOOM, DELIBERATELY. At true scale the business is ~79% of the
  //   bar and the Ward is ~8%; the old Cary bar existed to magnify that sliver. The
  //   page has spent its length asserting in words that what we take is small, and
  //   at true scale a reader simply sees it (Jacob, 2026-09-13).
  //   ⭐ All three bars share ONE scale — the largest total — so the incumbent's bar is
  //   visibly longer rather than merely labelled with a bigger number.
  function drawWhole(charged, received, rival){
    var max = Math.max(charged.total, rival.total) || 1;
    var seg = function(cls, v){ return v>0 ? '<div class="sb-seg '+cls+'" style="width:'+(v/max*100).toFixed(2)+'%"></div>' : ''; };
    $('w1').innerHTML = seg('c-food',charged.menu)+seg('c-tax',charged.tax)+seg('c-svc',charged.svc)+seg('c-proc',charged.fee);
    $('w2').innerHTML = seg('c-food',received.business)+seg('c-svc',received.courier)+seg('c-ward',received.ward)+seg('c-proc',received.proc);
    $('w3').innerHTML = seg('c-food',rival.menu)+seg('c-mark',rival.markup)+seg('c-tax',rival.tax)+seg('c-svc',rival.svc)+seg('c-proc',rival.fee);
    $('w1-tot').textContent=M(charged.total);
    $('w2-tot').textContent=M(received.total);
    $('w3-tot').textContent=M(rival.total);
    $('w-key').innerHTML =
      '<div class="k-food"><b>'+M(charged.menu)+'</b>Menu</div>'+
      '<div class="k-mark"><b>'+M(rival.markup)+'</b>Markup (theirs)</div>'+
      '<div class="k-tax"><b>'+M(charged.tax)+' · '+M(rival.tax)+'</b>Sales tax</div>'+
      '<div class="k-svc"><b>'+M(charged.svc)+'</b>Service charge</div>'+
      '<div class="k-ward"><b>'+M(received.ward)+'</b>The Ward</div>'+
      '<div class="k-proc2"><b>'+M(charged.fee)+' · '+M(rival.fee)+'</b>Processing · delivery fee</div>';
  }

  // ⭐ BOTH SIDES OF THE ORDER, IN ONE TABLE. This answered only what the BUSINESS
  //   keeps; the customer's half lived in a caption underneath. And the customer
  //   figure is the same on every incumbent row, which is not a simplification — a
  //   restaurant's PLAN changes its commission, not the consumer's fees. So the tiers
  //   are a difference between the incumbents that the customer never sees, while
  //   here the customer pays less AND the restaurant keeps more.
  //   ⛔ The incumbent figure carries a 15% menu markup and ours carries none, which
  //   is the whole comparison, and is why "Menu prices match in-store" is the first
  //   rule on the page.
  function drawVs(sub, ourRate, costHere, costAt){
    var svg=$('vs'); if(!svg) return;
    var rows=[['The Ward',ourRate,true]].concat(RIVALS.map(function(r){return [r[0],r[1],false];}));
    var W=1000,L=190,R=300,TOP=52,BH=26,GAP=11;
    var maxR=0.35, plot=W-L-R;
    var x=function(v){ return L+(v/maxR)*plot; };
    // \u2b50 THREE COLUMNS, LABELLED ONCE. Every row used to repeat "keeps" and
    //   "customer", and the one fact that decides the whole comparison \u2014 that the
    //   SAME DISH IS LISTED HIGHER THERE \u2014 was not in the table at all; it sat in a
    //   caption underneath among two other fee figures. The menu price is now the
    //   FIRST column, so the markup is the first thing read, and the headings carry
    //   the words so the rows carry only money (Jacob, 2026-09-13: "still not clear
    //   that restaurants jack up the prices, too many words which are also confusing").
    //   \u26d4 The commission is gone from the row text because the BAR already is it.
    var C3=W-8;
    // ⛔ ONLY WHAT VARIES. Menu and customer-total were identical down all five
    //   incumbent rows — five rows of apparatus for one changing number — and both are
    //   drawn better by the customer bars above (Jacob: "what is all of this for then").
    // ⛔ A BAR WITH NO LABEL MEANS NOTHING. The commission was stripped from the rows
    //   on the grounds that "the bar already is it" — which left the bar unnamed, while
    //   the footnote said "what the business PAYS" and the column said "KEEPS". Two
    //   framings, one figure, neither anchored (Jacob: "this table isn't saying much").
    var head='<text x="'+L+'" y="'+(TOP-13)+'" font-size="11" fill="currentColor" opacity="0.55" letter-spacing="0.6">COMMISSION</text>'+
             '<text x="'+C3+'" y="'+(TOP-13)+'" text-anchor="end" font-size="11" fill="currentColor" opacity="0.55" letter-spacing="0.6">COST OF DELIVERY</text>';

    var bars=rows.map(function(r,i){
      var y=TOP+i*(BH+GAP);
      var w=Math.max(1,x(r[1])-L);
      var cost=r[2]?M(costHere):M(costAt(r[1],0))+'–'+M(costAt(r[1],1)).replace('$','');
      var op=r[2]?'0.95':'0.7';
      var cell=function(cx,v){ return '<text x="'+cx+'" y="'+(y+14)+'" text-anchor="end" font-size="14" fill="currentColor" opacity="'+op+'" >'+v+'</text>'; };
      return '<rect x="'+L+'" y="'+y+'" width="'+w.toFixed(1)+'" height="'+BH+'" fill="'+(r[2]?'var(--cary-rule)':'var(--cary-rule)')+'" opacity="'+(r[2]?'1':'0.42')+'"/>'+
             '<text x="'+(L-10)+'" y="'+(y+14)+'" text-anchor="end" font-size="13.5" fill="currentColor"'+(r[2]?' font-weight="600"':' opacity="0.75"')+'>'+r[0]+'</text>'+
             '<text x="'+(L+w+8).toFixed(1)+'" y="'+(y+14)+'" font-size="12.5" fill="currentColor" opacity="'+op+'" >'+Math.round(r[1]*100)+'%</text>'+
             cell(C3,cost);
    }).join('');

    // ⭐ THE CAP IS A POINT, NOT A LEGEND ENTRY. The line was explained — "the dashed
    //   line is the 15% cap" — where what matters is how many tiers are on the wrong
    //   side of it. Counted from RIVALS so it cannot go stale if the list changes.
    var over=RIVALS.filter(function(r){ return r[1]>CAP; }).length;
    var cap=$('vs-cap');
    if(cap) cap.innerHTML='<b>'+over+' of these tiers sit above the 15% cap</b> — permanent in New York, San Francisco, Denver, Seattle and Washington DC.';
    var capX=x(CAP), H=TOP+rows.length*(BH+GAP)+16;
    return svg.innerHTML=
      '<line x1="'+capX.toFixed(1)+'" y1="'+(TOP-6)+'" x2="'+capX.toFixed(1)+'" y2="'+(H-14)+'" stroke="currentColor" stroke-width="1" stroke-dasharray="3 3" opacity="0.65"/>'+
      '<text x="'+(capX+5).toFixed(1)+'" y="'+(TOP-31)+'" font-size="12.5" fill="currentColor" opacity="0.65" letter-spacing="1">15% CAP</text>'+
      head+bars;
  }

  // The bar IS the money: segment widths are dollars, so the divisions fall
  // where the money actually puts them rather than where a ratio would.
  function calc(){
    var sub=+$('sub').value*100,
        taxR=+$('tax').value/100000,
        svcR=+$('svc').value/100,
        keepR=1-(+$('keep').value/100),
        courR=COUR;

    var tax=Math.round(sub*taxR);
    var svc=Math.round(sub*svcR);
    // ⛔ THE PAGE OFFERED SOMETHING THE PRODUCT DOES NOT DO. A second control asked
    // where the difference between the market rate and an in-house rate should go —
    // to the customer, or kept. Keeping it means charging the customer Stripe's rate,
    // paying $0.28 and pocketing $2.11, and we do not do that (Jacob, 2026-09-13:
    // "we just don't do that"). It was never two destinations; it was one behaviour
    // and one fiction. ⭐ ONE RATE, CHARGED AND PAID: a cheaper rail makes a cheaper
    // order, and that is the only version that can sit in the same document as
    // "processing is passed through at cost".
    var rate = owner==='inst' ? INHOUSE : PROC;
    var basis=sub+tax+svc;
    var procPaid= sub>0?Math.round(basis*(rate.r/10000))+rate.f:0;
    var total=sub+tax+svc+procPaid;

    var commission=Math.round(sub*(1-keepR));
    var business=sub-commission+tax;
    // ⛔ NO TIP ON THIS PAGE. The service charge is meant to BE the wage — an in-house
    //   waiter's scale — and a tip dial beside it says the opposite: that the wage is a
    //   base to be topped up. Couriers keep any tip they are given; the page does not
    //   model one, because modelling it concedes the argument (Jacob, 2026-09-13).
    var courier=Math.round(svc*courR);
    var pool=(svc-Math.round(svc*courR))+commission;
    var ward=pool;

    $('sub-v').textContent='$'+(sub/100).toFixed(0);
    $('tax-v').textContent=(+$('tax').value/1000).toFixed(3).replace(/0+$/,'').replace(/\.$/,'')+'%';
    $('svc-v').textContent=$('svc').value+'%';
    // ⭐ WRITTEN FROM COUR, NOT TYPED. It is the only place the courier's share is
    //   stated on this page, and it is injected from the constant the arithmetic uses,
    //   so the sentence and the bar cannot disagree. Kept on that condition (Jacob,
    //   2026-09-13: "we can leave it if it's connected to the knobs").
    $('cour-note').innerHTML='The courier is paid <b>'+Math.round(COUR*100)+'%</b> of it.';
    $('proc-v').textContent=(rate.r/100).toFixed(2).replace(/\.?0+$/,'')+'% + '+rate.f+'¢';
    $('keep-v').textContent=(+$('keep').value)+'% · '+M(commission);


    $('o-food').textContent=M(sub);
    $('o-tax').textContent=M(tax);
    $('o-svc').textContent=M(svc);
    // ⛔ §8.5 OF THE LICENCE: an amount represented to the customer as
    // reimbursement of processing cost may not exceed the processing cost. An
    $('o-proc').textContent=M(procPaid);
    $('o-total').textContent=M(total);

    $('p-rest').textContent=M(business);
    $('p-comm').textContent='−'+M(commission);
    $('p-cour').textContent=M(courier);
    $('p-plat').textContent=M(ward);
    $('p-proc').textContent=M(procPaid);
    $('p-total').textContent=M(business+courier+ward+procPaid);


    // ⭐ THE OTHER HALF OF THE ARGUMENT. The chart answers what the BUSINESS
    // pays; a reader's next question is always what THEY pay. The incumbents'
    // damage on that side is mostly menu markup — a restaurant raising prices
    // to survive a 30% commission has no reason to do it here.
    // ⛔ Service and delivery fees are published; the markup is not, and was a DIAL
    // until 2026-09-13 for exactly that reason — which had it backwards. The one
    // figure nobody publishes is the last one a reader should be invited to tune,
    // because tuning it moves the comparison this page exists to make.
    // ⭐ A MARKUP CANNOT MERELY EQUAL THE COMMISSION, because the commission is charged
    //   on the marked-up price: to come out whole a restaurant needs c/(1-c) — 17.6%
    //   against a 15% commission, 42.9% against 30%. So the dial is HOW MUCH OF IT THEY
    //   PASS ON, and the markup is derived per tier. That also gives every tier its own
    //   menu price; a flat markup gave all five the same customer total, which was the
    //   tell that the model was wrong.
    // ⛔ A SLIDER MADE EVERY NUMBER CONDITIONAL. Nothing could be quoted without a
    //   qualifier — "$77.04, at 50% pass-through" — and the page's strongest moments are
    //   flat statements. Worse, it asked the reader to set a variable that CANNOT CHANGE
    //   THE ANSWER: measured at 0, 25, 50, 75 and 100, our cost of delivery is $17.24 at
    //   every one (we do not mark up), and every incumbent tier costs more at every one.
    //   ⭐ So the assumption is shown as the SPAN it creates rather than a control someone
    //   has to operate: absorbed at one end, passed on at the other (Jacob: "we were just
    //   talking in somewhat concrete numbers and suddenly we're back in slider %s").
    var menuAt=function(rate,pass){ return Math.round(sub*(1+pass*rate/(1-rate))); };
    var custAt=function(rate,pass){ var m=menuAt(rate,pass);
      return m+Math.round(m*taxR)+Math.round(m*INCUMBENT_SERVICE)+INCUMBENT_DELIVERY; };
    // ⭐ THE ONE FIGURE THE MARKUP CANNOT SHUFFLE. Moving cost from the restaurant to the
    //   customer is exactly what a markup does, so either party read alone can be made to
    //   look fine. Against walking in, the cost of having the order DELIVERED is what both
    //   give up together, and it holds whoever bears it.
    var walkIn=sub+Math.round(sub*taxR);
    var costHere=(total-walkIn)+commission;
    var costAt=function(rate,pass){ return (custAt(rate,pass)-walkIn)+(sub-Math.round(menuAt(rate,pass)*(1-rate))); };
    var iFood=menuAt(CAP,1), iTotal=custAt(CAP,1);
    var iFee=Math.round(iFood*INCUMBENT_SERVICE), iTax=Math.round(iFood*taxR);
    drawVs(sub, 1-keepR, costHere, costAt);
    drawWhole({menu:sub, tax:tax, svc:svc, fee:procPaid, total:total},
              {business:business, courier:courier, ward:ward, proc:procPaid, total:total},
              {menu:sub, markup:iFood-sub, tax:iTax, svc:iFee, fee:INCUMBENT_DELIVERY, total:iTotal});
    // ⭐ THE COMPARISON THAT LOOKS LIKE IT GOES THE OTHER WAY. Our named rate is
    //   HIGHER than theirs — 22% against a capped 15% — and a reader has no reason to
    //   distrust that until someone points at what each is charged ON. Theirs is the
    //   smaller number because the thing it is applied to was made bigger, by them.
    //   ⛔ Nothing new is computed here: sub, iFood and both rates are already on the
    //   page, in the bars directly above. This says out loud the one step the reader
    //   would otherwise have to take on their own, and it is wired so it cannot drift
    //   from the figures it is describing.
    var wr=$('w-rates');
    if(wr) wr.innerHTML = sub>0
      ? '<b>The percentages are not directly comparable.</b> Their commission is charged against a '+
        'marked-up menu price; our service charge is calculated from the '+M(sub)+' counter price. '+
        'A '+Math.round(CAP*100)+'% commission taken on the marked-up price needs a '+
        (Math.round(CAP/(1-CAP)*1000)/10)+'% rise to leave the restaurant whole — which is '+
        'where their '+M(iFood)+' comes from.'
      : '';

    var vc=$('vs-cust');
    if(vc) vc.innerHTML = sub>0
      ? (function(){
          var lo=costAt(CAP,0), hi=costAt(CAP,1);
          return '<b>Delivered through The Ward the order costs '+M(costHere)+' more than walking in.</b> '+
                 'Through the capped 15% tier, '+M(lo)+'\u2013'+M(hi)+' \u2014 the span is whether the restaurant absorbs the commission or passes it to you in the menu price. '+
                 'It costs more either way; only who pays it changes.';
        })()
      : '';
    // ⛔ THE MONTH IS NOT THIS PAGE'S TO ASSUME. "Orders / restaurant / month" was a
    //   dial set to 40, implying $2,200 of trade — while The Ask, which actually models
    //   volume, assumes $8,000. The same restaurant, 3.6x apart, and this page was
    //   underselling its own best sentence by that factor. The monthly figure now comes
    //   from The Ask's number, so the two cannot disagree, and it is held to that by
    //   tools/claims-pages-agree.mjs rather than by anyone remembering.
    //   ⭐ Computed in DOLLARS of trade, not rounded per order and multiplied.
    var vm=$('vs-month');
    if(vm){
      var lo=Math.round(MONTHLY*RIVALS[0][1]), hi=Math.round(MONTHLY*RIVALS[RIVALS.length-1][1]);
      var ours=Math.round(MONTHLY*(+$('keep').value/100));
      vm.innerHTML='<b>At '+MB(MONTHLY)+' of food a month</b>, the business pays '+MB(ours)+' in fees here. The same trade costs '+
        MB(lo)+' to '+MB(hi)+' on the platforms above — <b>'+MB(lo-ours)+' to '+MB(hi-ours)+' a month kept, '+
        MB((lo-ours)*12)+' to '+MB((hi-ours)*12)+' a year.</b>';
    }
  }

  ['sub','tax','svc','keep'].forEach(function(id){ $(id).addEventListener('input',calc); });

  // ⛔ NO GRIP. The bar had a drag handle on the courier/Ward division, and there
  //   is nothing to experiment with: the payouts are CALCULATED from the stated
  //   percentages applied to one food subtotal (Jacob, 2026-09-13: "there's nothing
  //   to slide, no experiment here"). A handle is a promise that the number is the
  //   reader's to choose, and this one is not — it is policy, stated, the same way
  //   the restaurant's fee and the service charge are stated above it.
  //   ⭐ It also takes the last of the pointer-capture drag code with it, which never
  //   worked on touch: no touch-action, no pointercancel, and a 13px target.

  function pickOne(hostId, fn){
    Array.prototype.forEach.call($(hostId).querySelectorAll('button'),function(b){
      b.addEventListener('click',function(){
        Array.prototype.forEach.call($(hostId).querySelectorAll('button'),function(x){x.setAttribute('aria-pressed','false');});
        b.setAttribute('aria-pressed','true'); fn(b.dataset.v, b); calc();
      });
    });
  }
  pickOne('ownersel', function(v,b){
    owner=v;
    $('owner-v').textContent=b.textContent;
    // ⛔ An institution that owns the rails IS the acquirer, so there is no
    // processor to choose. Leaving Stripe lit while the rate read 0.25% + 10¢
    // showed a selection the arithmetic was ignoring.
    $('procsel').hidden = owner==='inst';
    $('proc-note').innerHTML = owner==='inst'
      ? 'Processed in-house at a <b>scenario rate, not a quote</b> — an acquirer that is also the issuer internalises interchange, and no published figure covers that. <b>The Ward is a team inside that institution here</b>, so the cheaper rail and the Ward’s share land in the same pocket.'
      : 'Stripe and Square publish <b>2.9% + 30¢</b> for online payments. Adyen publishes <b>$0.13 + interchange + scheme fees + 0.60%</b> — the modeled figure adds typical US card-not-present interchange and scheme fees to that markup. ';
  });

  // ⭐ The Ask hands the shape over in the URL, so the two pages agree about
  // who owns the rails instead of each asking separately.
  (function(){
    var q=(location.search.match(/[?&]owner=(\w+)/)||[])[1];
    if(q!=='inst') return;
    var b=$('ownersel').querySelectorAll('button')[1];
    if(b) b.click();
  })();

  Array.prototype.forEach.call($('procsel').querySelectorAll('button'),function(b){
    b.addEventListener('click',function(){
      Array.prototype.forEach.call($('procsel').querySelectorAll('button'),function(x){x.setAttribute('aria-pressed','false');});
      b.setAttribute('aria-pressed','true');
      PROC={r:+b.dataset.r, f:+b.dataset.f};
      calc();
    });
  });
  calc();
})();

